fn project(row: &User, fields: &BTreeSet<String>) -> Result<Value, ApiError> {
    let mut value = serde_json::to_value(row)?;
    let map = value.as_object_mut().ok_or(ApiError::Internal)?;   // non-object: panic avoided
    for name in fields {
        if !SELECTABLE.contains(name.as_str()) {
            return Err(ApiError::InvalidArgument(format!("unknown field {name}")));
        }
    }
    map.retain(|k, _| fields.contains(k));
    Ok(value)
}

