fn trim(mask: &FieldMask, full: &User) -> Result<User, ApiError> {
    let mut out = User::default();
    for path in &mask.paths {
        match path.as_str() {
            "id"         => out.id = full.id,
            "email"      => out.email = full.email.clone(),
            "created_at" => out.created_at = full.created_at,
            other => return Err(ApiError::InvalidArgument(format!("unknown path {other}"))),
        }
    }
    Ok(out)
}
